declare(strict_types=1);session_start();require __DIR__.'/config.php';require dirname(__DIR__).'/api/bootstrap.php';if(empty($_SESSION['gpme_maint'])){http_response_code(403);exit('Accès refusé');}$db=gpme_db();$rows=$db->query('SELECT * FROM feedback ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="retours-eleves-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['id','statut','ressource_id','ressource','section','type','commentaire','date'], ';');foreach($rows as $r)fputcsv($o,[$r['id'],$r['status'],$r['resource_id'],$r['resource_title'],$r['section'],$r['category'],$r['comment'],$r['created_at']],';');fclose($o);?>